import "server-only";
import * as contentful from "contentful";

if (!process.env.CONTENTFUL_SPACE_ID) {
  throw new Error("CONTENTFUL_SPACE_ID is missing from .env.local");
}
if (!process.env.CONTENTFUL_DELIVERY_TOKEN) {
  throw new Error("CONTENTFUL_DELIVERY_TOKEN is missing from .env.local");
}

/** Serves published content from Contentful's CDN. Use this for all production reads. */
export const deliveryClient = contentful.createClient({
  space: process.env.CONTENTFUL_SPACE_ID,
  accessToken: process.env.CONTENTFUL_DELIVERY_TOKEN,
  host: "cdn.contentful.com",
});

// Preview client is initialized lazily — preview token is optional.
// Call getPreviewClient() in Next.js Draft Mode handlers only.
const _previewClient =
  process.env.CONTENTFUL_PREVIEW_TOKEN
    ? contentful.createClient({
        space: process.env.CONTENTFUL_SPACE_ID,
        accessToken: process.env.CONTENTFUL_PREVIEW_TOKEN,
        host: "preview.contentful.com",
      })
    : null;

/**
 * Returns the preview client for Next.js Draft Mode.
 * Throws if CONTENTFUL_PREVIEW_TOKEN is not set — call only from preview/draft handlers.
 */
export function getPreviewClient(): contentful.ContentfulClientApi<undefined> {
  if (!_previewClient) {
    throw new Error(
      "CONTENTFUL_PREVIEW_TOKEN is missing from .env.local. " +
        "Add it to enable Draft Mode / Content Preview API.",
    );
  }
  return _previewClient;
}

