"use server";

import type { EntrySkeletonType } from "contentful";
import { deliveryClient, getPreviewClient } from "./client";

export interface GetEntriesOptions {
  limit?: number;
  /** Contentful order string, e.g. "-sys.updatedAt" */
  order?: string;
  /** Linked-entry depth to resolve (1–10). Default: 2 */
  include?: number;
}

/**
 * Fetch all published entries of a content type.
 * Tag results for ISR cache invalidation:
 *   Use revalidateTag(contentType) in your webhook handler.
 */
export async function getEntriesByType<T extends EntrySkeletonType>(
  contentType: string,
  options: GetEntriesOptions = {},
) {
  const { items } = await deliveryClient.getEntries<T>({
    content_type: contentType,
    limit: options.limit ?? 100,
    order: options.order
      ? [options.order as Parameters<typeof deliveryClient.getEntries>[0]["order"][number]]
      : undefined,
    include: options.include ?? 2,
  });
  return items;
}

/** Fetch a single published entry by its Contentful entry ID. */
export async function getEntryById<T extends EntrySkeletonType>(id: string) {
  return deliveryClient.getEntry<T>(id);
}

/**
 * Fetch a single published entry by content type and `slug` field value.
 * Assumes your content type has a short-text `slug` field.
 * Returns the first match or null.
 */
export async function getEntryBySlug<T extends EntrySkeletonType>(
  contentType: string,
  slug: string,
) {
  const { items } = await deliveryClient.getEntries<T>({
    content_type: contentType,
    "fields.slug": slug,
    limit: 1,
  } as Parameters<typeof deliveryClient.getEntries>[0]);
  return items[0] ?? null;
}

/**
 * Fetch a draft entry via the Content Preview API.
 * Use this inside Next.js Draft Mode (`draftMode().isEnabled`) to show unpublished content.
 * Requires CONTENTFUL_PREVIEW_TOKEN to be set.
 */
export async function getEntryPreview<T extends EntrySkeletonType>(id: string) {
  return getPreviewClient().getEntry<T>(id);
}

