import crypto from "crypto";
import { revalidateTag, revalidatePath } from "next/cache";

export interface ContentfulWebhookPayload {
  sys: {
    type: "Entry" | "Asset" | "DeletedEntry" | "DeletedAsset";
    id: string;
    /** Content type ID (e.g. "article") — present for Entry events only */
    contentType?: { sys: { id: string } };
    /** Present only if the entry has been published at least once */
    publishedVersion?: number;
    updatedAt: string;
  };
  fields?: Record<string, unknown>;
}

/**
 * Verifies the Contentful webhook secret.
 *
 * Contentful does not compute an HMAC — it sends the secret verbatim as
 * the `x-contentful-secret` header. Timing-safe comparison prevents
 * oracle attacks on the string compare.
 */
export function verifyWebhookSecret(
  secretHeader: string,
  secret: string,
): boolean {
  const a = Buffer.from(secretHeader, "utf8");
  const b = Buffer.from(secret, "utf8");
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

/**
 * Handle a Contentful webhook event.
 *
 * @param payload - Parsed JSON body from the webhook request
 * @param topic   - Value of the `x-contentful-topic` request header
 *                  e.g. "ContentManagement.Entry.publish"
 */
export async function handleContentfulEvent(
  payload: ContentfulWebhookPayload,
  topic: string,
): Promise<void> {
  const contentType =
    payload.sys.contentType?.sys.id ?? payload.sys.type.toLowerCase();

  // Skip auto-saves of drafts that have never been published.
  // `sys.publishedVersion` is absent on entries that exist only as drafts.
  // This prevents cache busts while an editor is actively writing.
  if (topic.includes(".save") && payload.sys.publishedVersion === undefined) {
    console.log(
      `[contentful] Skipping revalidation for unpublished draft save: ${payload.sys.id}`,
    );
    return;
  }

  if (topic.includes(".publish") || topic.includes(".unpublish")) {
    revalidateTag(contentType);
    // TODO: Narrow this to specific paths rather than a full-layout revalidation —
    // e.g. revalidatePath(`/${contentType}`) or per-slug if your payload includes one.
    revalidatePath("/", "layout");
    console.log(
      `[contentful] Revalidated tag "${contentType}" and path "/" on ${topic}`,
    );
  } else {
    revalidateTag(contentType);
    console.log(`[contentful] Revalidated tag "${contentType}" on ${topic}`);
  }
}

