import { headers } from "next/headers";
import {
  handleContentfulEvent,
  verifyWebhookSecret,
} from "@/infra/contentful/webhooks";

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const secretHeader = headersList.get("x-contentful-secret");

  if (!secretHeader) {
    return new Response("Bad request", { status: 400 });
  }

  if (!process.env.CONTENTFUL_WEBHOOK_SECRET) {
    console.error("[contentful webhook] CONTENTFUL_WEBHOOK_SECRET is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  if (!verifyWebhookSecret(secretHeader, process.env.CONTENTFUL_WEBHOOK_SECRET)) {
    console.error("[contentful webhook] Invalid x-contentful-secret header");
    return new Response("Unauthorized", { status: 401 });
  }

  // Read the topic header before parsing the body — it tells us the event type
  // (publish, unpublish, save, delete) which the JSON body does not contain.
  const topic = headersList.get("x-contentful-topic") ?? "";

  // Parse FIRST — malformed JSON is a permanent error (400, no retry).
  let event;
  try {
    event = JSON.parse(body);
  } catch (err: unknown) {
    console.error("[contentful webhook] Malformed JSON", err);
    return new Response("Bad request", { status: 400 });
  }

  // Handler errors are 500 so Contentful retries — distinct from 4xx above.
  try {
    await handleContentfulEvent(event, topic);
    return new Response("OK", { status: 200 });
  } catch (err: unknown) {
    console.error("[contentful webhook] Handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}
